(()=>{const role=document.body.dataset.accountRole;let session;try{session=JSON.parse(sessionStorage.getItem('finsyndeo-whole-review-preview-session')||'null');}catch(e){}if(!session||session.role!==role)return;const key='finsyndeo-whole-review-preview-account-'+encodeURIComponent(session.email),draftKey=role==='applicant'?'finsyndeo-whole-review-unified-draft-v1':'finsyndeo-whole-review-provider-draft-v1';const nav=document.querySelector('header nav');const link=document.createElement('a');link.href='My-account.html';link.textContent='My account';nav.append(link);nav.querySelectorAll('a').forEach(a=>{if(a.textContent.trim()==='Sign In'||a.textContent.trim()==='Sign in')a.hidden=true;});
if(role==='provider'){let timer;function mirror(){let account;try{account=JSON.parse(localStorage.getItem(key)||'null');}catch(e){}account??={assessments:[]};try{account.provider=JSON.parse(localStorage.getItem(draftKey)||'null');localStorage.setItem(key,JSON.stringify(account));localStorage.setItem('finsyndeo-whole-review-provider-preview-owner',session.email);}catch(e){}}['input','change','click'].forEach(event=>document.addEventListener(event,()=>{clearTimeout(timer);timer=setTimeout(mirror,200);}));window.addEventListener('pagehide',mirror);return;}const toolbar=document.querySelector('.review-banner')||document.querySelector('.draft-state')||document.querySelector('header nav');const saveButton=document.createElement('button');saveButton.type='button';saveButton.className='mini';saveButton.textContent='Save to my assessments';toolbar.append(saveButton);let timer;
function saveAssessment(explicit=false){let draft;try{draft=JSON.parse(localStorage.getItem(draftKey)||'null');}catch(e){}if(!draft)return;let account;try{account=JSON.parse(localStorage.getItem(key)||'null');}catch(e){}account??={assessments:[]};const existing=sessionStorage.getItem('finsyndeo-whole-review-active-assessment'),id=existing||'assessment-'+Date.now(),previous=account.assessments.find(a=>a.id===id);const applicant=document.querySelector('#applicant').value,name=applicant==='individual'?document.querySelector('#pb-name').value:document.querySelector('#company-name').value;const item={id,name:name||'Untitled assessment',kind:applicant==='individual'?'Private banking':applicant==='institution'?'Correspondent / payment accounts':document.querySelector('#account-type').selectedOptions[0].textContent,draft,updated:new Date().toISOString(),notifications:previous?.notifications||{enabled:false,threshold:90}};account.assessments=account.assessments.filter(a=>a.id!==id);account.assessments.push(item);localStorage.setItem(key,JSON.stringify(account));sessionStorage.setItem('finsyndeo-whole-review-active-assessment',id);if(explicit)saveButton.textContent='Saved to my assessments';}
saveButton.onclick=()=>setTimeout(()=>saveAssessment(true),50);['input','change','click'].forEach(event=>document.addEventListener(event,()=>{clearTimeout(timer);timer=setTimeout(()=>saveAssessment(),200);}));window.addEventListener('pagehide',()=>saveAssessment());})();
